public static Node getCurrentNode(int defaultPort) {
    KylinConfig kylinConfig;
    String configNodeStr;
    Node result;
    Map<String, String> nodeProperties;
    try {
        kylinConfig = KylinConfig.getInstanceFromEnv();
        configNodeStr = kylinConfig.getStreamingNode();
        if (configNodeStr != null) {
            result = Node.from(configNodeStr);
        } else {
            result = new Node(getLocalhostName(), defaultPort);
        }
        nodeProperties = kylinConfig.getStreamingNodeProperties();
        result.setProperties(nodeProperties);
    } catch (RuntimeException e) {
        // Log the exception and handle it appropriately
        System.err.println("RuntimeException occurred: " + e.getMessage());
        throw e; // Re-throw if recovery is not possible
    }
    return result;
}
